        audioValid: true,
        audioSource: decrypted.source,
        audio_converter_endpoint: converterEndpoint,
        audio_normalization_policy: 'evolution_audio_converter_process_audio_v1',
        audio_media_url: audio.url || source.audioUrl || null,
