        audio: converted.base64,
        data: converted.base64,
        format: 'ogg',
        mimetype: 'audio/ogg',
        path: 'audio.ogg',
        media_warning: null,
      },
    });
  } catch (error) {
    output.push({
      json: {
        ...fallbackJson,
        media_error: error?.message || String(error),
      },
      binary: item.binary,
    });
  }
}

return output;

