function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

// ======================================
// TOOL GOVERNANCE
// ======================================

const toolRevalidationTriggers = [
  'manda de novo',
  'manda novamente',
  'reenvia',
  'link deu erro',
  'link falhou',
  'qual era aquele imovel',
  'qual era aquele imóvel',
  'abre mais aquele apartamento',
  'detalhes do imovel anterior',
  'aquele que voce falou',
  'tinha comentado',
  'ainda faz sentido',
  'voltei aqui',
];

const normalizedMessage =
  normalize(mensagemCliente);

const requiresToolRevalidation =
  toolRevalidationTriggers.some((trigger) =>
    normalizedMessage.includes(
      normalize(trigger)
    )
  );

const propertyIntentTriggers = [
  'imovel',
  'imoveis',
  'opcao',
  'opcoes',
  'sugestao',
  'sugestoes',
  'recomendacao',
  'recomendacoes',
  'link',
  'visita',
  'visitar',
  'disponivel',
  'disponiveis',
  'pode mandar',
  'manda uma',
  'me manda',
  'se tiver',
  'tem algo',
];

const regionIntentTriggers = [
  'bessa',
  'jardim oceania',
  'cabo branco',
  'tambau',
  'manaira',
  'intermares',
  'ponta de campina',
  'altiplano',
];

const hasPropertyIntent =
  propertyIntentTriggers.some((trigger) =>
    normalizedMessage.includes(
      normalize(trigger)
    )
  );

const hasRegionContext =
  Boolean(
    operational.preferred_regions?.length ||
    deal.location_preference ||
    regionIntentTriggers.some((trigger) =>
      normalizedMessage.includes(
        normalize(trigger)
      )
    )
  );

const hasBudgetContext =
  Boolean(
    operational.budget_min ||
    operational.budget_max ||
    deal.budget_min ||
    deal.budget_max ||
    /(?:r\$|\b\d+\s*(?:mil|k)\b)/i.test(mensagemCliente)
  );

const hasTypeContext =
  Boolean(
    operational.property_type ||
    deal.property_type ||
    /\b(?:apartamento|apto|ape|flat|studio|casa|cobertura|terreno|\d+\s*quartos?)\b/i.test(mensagemCliente)
  );

const hasObjectiveContext =
  Boolean(
    operational.objective ||
    deal.intent ||
    lead.ai_last_intent ||
    /\b(?:morar|investir|investimento|alugar|familia|temporada|short stay)\b/i.test(mensagemCliente)
  );

const propertyPresentationDue =
  requiresToolRevalidation ||
  (
    hasPropertyIntent &&
    (
      hasRegionContext ||
      hasBudgetContext ||
      hasTypeContext ||
      hasObjectiveContext
    )
  );

const orchestratedNextBestAction =
  propertyPresentationDue
    ? 'apresentar_opcoes_aderentes'
    : (
      runtime.next_best_action ||
      'descobrir_contexto'
    );

