  ...leadMeta,
  ...dealMeta,
  ...conversationMeta,
  ...opMeta,
};

const runtimeMemory = {
  funnel_stage: operationalContext.funnel_stage || null,
  favorite_property: operationalContext.favorite_property || null,
  properties_sent_count: operationalContext.properties_sent_count || 0,
  visit_interest_score: operationalContext.visit_interest_score || 0,
  followup_enabled: operationalContext.followup_enabled || false,
};

