    tenant_id: input.tenant_id || lead.tenant_id || null,
    lead_id: lead.id || input.lead_id || null,
    deal_id: deal.id || input.deal_id || null,
    conversation_id: conversation.id || input.conversation_id || null,
    sessionId: input.sessionId || input.telefoneCompleto || null,
    telefoneCompleto: input.telefoneCompleto || input.phone || null,
    remoteJid: input.remoteJid || null,
    phone: lead.phone || input.phone || null,
    lead,
    deal,
    conversation,
    recent_messages: recentMessages,
    operational_context: operationalContext,
    runtime_memory: runtimeMemory,
    metadata_unificada: metadataUnificada,
    mensagemCliente: input.mensagemCliente || input.mensagem || '',
    messageType: input.messageType || null,
    instance: input.instance || null,
    external_message_id: input.external_message_id || null,
    origemLead: input.origemLead || null,
    lead_avatar_url: input.lead_avatar_url || null,
