    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

function compactArray(arr = []) {
  return arr
    .filter(Boolean)
    .map((v) => String(v).trim())
    .filter(Boolean);
}

const input = $json || {};

const lead =
  input.lead ||
  {};

