const propertyIntentSignal =
  normalizedConversation.includes('imovel') ||
  normalizedConversation.includes('imoveis') ||
  normalizedConversation.includes('opcao') ||
  normalizedConversation.includes('opcoes') ||
  normalizedConversation.includes('sugestao') ||
  normalizedConversation.includes('sugestoes') ||
  normalizedConversation.includes('recomendacao') ||
  normalizedConversation.includes('recomendacoes') ||
  normalizedConversation.includes('link') ||
  normalizedConversation.includes('pode mandar') ||
  normalizedConversation.includes('manda uma') ||
  normalizedConversation.includes('me manda') ||
  normalizedConversation.includes('se tiver') ||
  normalizedConversation.includes('tem algo') ||
  normalizedConversation.includes('disponivel') ||
  normalizedConversation.includes('disponiveis') ||
  visitIntentSignal ||
  revisitInventorySignal;

const followupSignal =
  spouseDecisionSignal ||
  normalizedConversation.includes('vou pensar') ||
  normalizedConversation.includes('depois eu vejo') ||
  normalizedConversation.includes('vou analisar');

// ============================================
// INVENTORY GOVERNANCE
// ============================================

const outboundPropertyMessages =
  recentMessages.filter((m) => {
    const text =
      normalize(m.content || '');

    return (
      (
        m.direction === 'outbound' ||
        m.sender_type === 'agent'
      ) &&
      (
        text.includes('https://jurema.app/imovel') ||
        text.includes('https://juremabksimoveis.com.br/imoveis')
      )
    );
  });

const propertiesSentCount =
  outboundPropertyMessages.length;

const inventoryFatigue =
  propertiesSentCount >= 6;

// ============================================
// FAVORITE PROPERTY
// ============================================

let favoriteProperty =
  existingOperationalContext.favorite_property ||
  null;

const propertyMatch =
  allConversationText.match(
    /(cabo branco|tambau|bessa|manaira|jardim oceania|intermares|ponta de campina|altiplano)/i
  );

if (propertyMatch) {
  favoriteProperty =
    propertyMatch[1];
}

// ============================================
// QUALIFICATION DEPTH
// ============================================

let qualificationDepth = 0;

if (lead.name) {
  qualificationDepth += 1;
}

if (
  deal.location_preference ||
  beachInterest
) {
  qualificationDepth += 1;
}

if (deal.property_type) {
  qualificationDepth += 1;
}

if (
  deal.budget_min ||
  deal.budget_max
) {
  qualificationDepth += 2;
}

if (deal.bedrooms) {
  qualificationDepth += 1;
}

if (deal.timeline) {
  qualificationDepth += 1;
}

if (
  financingSignal ||
  fgtsSignal
) {
  qualificationDepth += 1;
}

const hasRegionContext =
  Boolean(
    deal.location_preference ||
    propertyMatch?.[1] ||
    beachInterest
  );

const hasBudgetContext =
  Boolean(
    deal.budget_min ||
    deal.budget_max ||
    /(?:r\$|\b\d+\s*(?:mil|k)\b)/i.test(mensagemCliente)
  );

const hasTypeContext =
  Boolean(
    deal.property_type ||
    /\b(?:apartamento|apto|ape|flat|studio|casa|cobertura|terreno|\d+\s*quartos?)\b/i.test(mensagemCliente)
  );

const hasObjectiveContext =
  Boolean(
    deal.intent ||
    lead.ai_last_intent ||
    /\b(?:morar|investir|investimento|alugar|familia|temporada|short stay)\b/i.test(mensagemCliente)
  );

const propertyPresentationDue =
  propertyIntentSignal &&
  (
    hasRegionContext ||
    hasBudgetContext ||
    hasTypeContext ||
    hasObjectiveContext ||
    revisitInventorySignal
  );

// ============================================
// FUNNEL ENGINE
// ============================================

let funnelStage =
  'lead_novo';

if (
  qualificationDepth >= 4
) {
  funnelStage =
    'qualificando';
}

if (
  propertiesSentCount >= 2
) {
  funnelStage =
    'matching';
}

if (
  spouseDecisionSignal ||
  revisitInventorySignal ||
  favoriteSignal
) {
  funnelStage =
    'comparando';
}

if (
  visitIntentSignal
) {
  funnelStage =
    'visita';
}

if (
  followupSignal &&
  !visitIntentSignal
) {
  funnelStage =
    'followup';
}

// ============================================
// DECISION STYLE
// ============================================

let decisionStyle =
  existingOperationalContext.decision_style ||
  null;

if (
  spouseDecisionSignal ||
  deal.decision_maker === 'casal'
) {
  decisionStyle =
    'casal';
}

// ============================================
// VISIT INTEREST SCORE
// ============================================

let visitInterestScore =
  Number(
    existingOperationalContext.visit_interest_score || 0
  );

if (visitIntentSignal) {
  visitInterestScore += 2;
}

if (favoriteSignal) {
  visitInterestScore += 1;
}

if (revisitInventorySignal) {
  visitInterestScore += 1;
}

visitInterestScore =
  Math.min(10, visitInterestScore);

// ============================================
// FOLLOWUP
// ============================================

const followupEnabled =
  funnelStage === 'followup' ||
  spouseDecisionSignal;

// ============================================
// NEXT BEST ACTION
// ============================================

let nextBestAction =
  'descobrir_contexto';

if (inventoryFatigue) {
  nextBestAction =
    'reduzir_inventory';
}

switch (funnelStage) {
  case 'lead_novo':
    nextBestAction =
      'descobrir_contexto';
    break;

  case 'qualificando':
    nextBestAction =
      'aprofundar_criterios';
    break;

  case 'matching':
    nextBestAction =
      'apresentar_opcoes_aderentes';
    break;

  case 'comparando':
    nextBestAction =
      spouseDecisionSignal
        ? 'acompanhar_decisao_casal'
        : 'consolidar_favorito';
    break;

  case 'visita':
    nextBestAction =
      'facilitar_agendamento';
    break;

  case 'followup':
    nextBestAction =
      'manter_radar_contextual';
    break;
}

if (propertyPresentationDue) {
  nextBestAction =
    'apresentar_opcoes_aderentes';
}

// ============================================
// REGIONS
// ============================================

const preferredRegions =
  compactArray([
    deal.location_preference,
    propertyMatch?.[1] || null,
    beachInterest ? 'praia' : null,
  ]);

// ============================================
// METADATA
// ============================================

const metadata = {
  source:
    'yzi_operational_runtime',

  updated_at:
    new Date().toISOString(),

  updated_from_message:
    mensagemCliente,

  behavioral_signals: {
    beach_interest:
      beachInterest,

    financing_signal:
      financingSignal,

    fgts_signal:
      fgtsSignal,

    credit_letter_signal:
      creditLetterSignal,

    spouse_decision_signal:
      spouseDecisionSignal,

    revisit_inventory_signal:
      revisitInventorySignal,

    favorite_signal:
      favoriteSignal,

    visit_intent_signal:
      visitIntentSignal,

    property_intent_signal:
      propertyIntentSignal,

    property_presentation_due:
      propertyPresentationDue,
  },

  runtime: {
    qualification_depth:
      qualificationDepth,

    inventory_fatigue:
      inventoryFatigue,

    properties_sent_count:
      propertiesSentCount,

    next_best_action:
      nextBestAction,

    property_presentation_due:
      propertyPresentationDue,
  }
};

// ============================================
// FINAL OPERATIONAL CONTEXT
// ============================================

const operationalContext = {
  tenant_id:
    tenantId,

  conversation_id:
    conversationId,

  lead_id:
    leadId,

  lead_name:
    lead.name || null,

  funnel_stage:
    funnelStage,

  decision_style:
    decisionStyle,

  objective:
    deal.intent ||
    lead.ai_last_intent ||
    null,

  preferred_regions:
    preferredRegions,

  property_type:
    deal.property_type ||
    null,

  bedrooms:
    deal.bedrooms ||
    null,

  budget_min:
    deal.budget_min ||
    null,

  budget_max:
    deal.budget_max ||
    null,

  beach_interest:
    beachInterest,

  financing_signal:
    financingSignal,

  fgts_signal:
    fgtsSignal,

  credit_letter_signal:
    creditLetterSignal,

  favorite_property:
    favoriteProperty,

  visit_interest_score:
    visitInterestScore,

  followup_enabled:
    followupEnabled,

  property_presentation_due:
    propertyPresentationDue,

  metadata,
};

// ============================================
// OUTPUT - PROJECAO ESTRITA
// ============================================

return [{
  json: {
    tenant_id: input.tenant_id || tenantId || null,
