async function supabaseRequest({ baseUrl, apiKey, method, path, qs = {}, body, prefer }) {
  const cleanBase = String(baseUrl).replace(/\/+$/, '');
  const cleanPath = String(path).startsWith('/') ? path : '/' + path;
  const headers = {
    apikey: apiKey,
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json',
  };
  if (prefer) headers.Prefer = prefer;
  const options = { method, url: cleanBase + cleanPath, qs, headers, json: true };
  if (body !== undefined) options.body = body;
  return await n8nHttpRequest.call(this, options);
}

function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function firstText(...values) {
  for (const value of values) {
    const text = String(value ?? '').trim();
    if (text) return text;
  }
  return '';
}

function normalizePhone(value) {
  return String(value ?? '').replace(/\D/g, '');
}

function recentText(messages) {
  return (messages || [])
    .map((m) => (m.direction === 'outbound' || m.sender_type === 'agent' ? 'Ju: ' : 'Cliente: ') + (m.content || ''))
    .filter(Boolean)
    .join('\n');
}

function pickDelaySeconds(metadata) {
  const strategy = asObject(metadata.strategy);
  const goal = String(strategy.goal || metadata.followup_type || '').toLowerCase();
  const emotional = goal.includes('emoc') || goal.includes('retomar_interesse');
  const curation = goal.includes('curadoria') || goal.includes('opcao') || goal.includes('imovel');
  const min = emotional ? 5 : curation ? 4 : 2;
  const max = emotional ? 9 : curation ? 7 : 4;
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const baseUrl = 'https://dwmbklfkrtumfaxrbxio.supabase.co';
const apiKey = $env.SUPABASE_SERVICE_ROLE_KEY || $env.JUREMA_SUPABASE_SERVICE_ROLE_KEY;
if (!apiKey) throw new Error('SUPABASE_SERVICE_ROLE_KEY nao configurada no ambiente n8n.');
const tenantId = '82cc7aa9-fc6e-4f37-8d8e-8a71c1691361';
const now = new Date().toISOString();

const dueTasks = await supabaseRequest.call(this, {
  baseUrl,
  apiKey,
  method: 'GET',
  path: '/rest/v1/follow_up_tasks',
  qs: {
    select: '*',
    due_at: 'lte.' + now,
    status: 'eq.pendente',
    order: 'priority.desc,due_at.asc',
    limit: 5,
  },
});

const tasks = Array.isArray(dueTasks) ? dueTasks : [];
const output = [];

for (const task of tasks) {
  const metadata = asObject(task.metadata);
  const leadId = firstText(task.lead_id, metadata.lead_id);
  if (!leadId) continue;

  let lead = null;
  try {
    const leads = await supabaseRequest.call(this, {
      baseUrl,
      apiKey,
      method: 'GET',
      path: '/rest/v1/leads',
      qs: { select: '*', id: 'eq.' + leadId, limit: 1 },
    });
    lead = Array.isArray(leads) ? leads[0] : leads;
  } catch (error) {
    lead = null;
  }
  if (!lead) continue;

  const conversations = await supabaseRequest.call(this, {
    baseUrl,
    apiKey,
    method: 'GET',
    path: '/rest/v1/conversations',
    qs: {
      select: '*',
      lead_id: 'eq.' + lead.id,
      order: 'updated_at.desc',
      limit: 1,
    },
  });
  const conversation = Array.isArray(conversations) ? conversations[0] : conversations;
  if (conversation?.ai_paused === true) continue;

  const deals = await supabaseRequest.call(this, {
    baseUrl,
    apiKey,
    method: 'GET',
    path: '/rest/v1/jurema_deals',
    qs: {
      select: '*',
      lead_id: 'eq.' + lead.id,
      order: 'updated_at.desc',
      limit: 1,
    },
  });
  const deal = Array.isArray(deals) ? deals[0] : deals;

  const recentDesc = conversation?.id
    ? await supabaseRequest.call(this, {
        baseUrl,
        apiKey,
        method: 'GET',
        path: '/rest/v1/conversation_messages',
        qs: {
          select: 'direction,sender_type,content,message_type,created_at',
          conversation_id: 'eq.' + conversation.id,
          order: 'created_at.desc',
          limit: 12,
        },
      })
    : [];
  const recentMessages = (Array.isArray(recentDesc) ? recentDesc : []).reverse();

  const conversationContext = asObject(metadata.conversation_context);
  const behavioralState = asObject(metadata.behavioral_state);
  const strategy = asObject(metadata.strategy);
  const telefone = normalizePhone(firstText(conversation?.phone_normalized, conversation?.phone, lead.phone, lead.phone_normalized));
  if (!telefone) continue;

  const internalEvent = {
    event_type: 'followup_resume',
    followup_type: firstText(metadata.followup_type, task.trigger_reason, 'momentum_recovery'),
    lead_id: lead.id,
    task_id: task.id,
    context: {
      bairro: firstText(conversationContext.bairro, deal?.location_preference, lead.metadata?.bairro_interesse),
      ultimo_imovel: firstText(conversationContext.property_reference, conversationContext.ultimo_imovel, metadata.property_reference),
      motivo: firstText(task.trigger_reason, strategy.goal, 'retomar_contexto'),
    },
    behavioral_state: behavioralState,
    strategy,
  };

  const eventText = [
    '[EVENTO_INTERNO_FOLLOWUP]',
    JSON.stringify(internalEvent),
    'Retome a conversa em uma mensagem curta, natural e consultiva. Nao diga que e automacao. Nao peca permissao para retomar. Use o historico e, se houver imovel/contexto suficiente, apresente ou reancore antes de perguntar.',
  ].join('\n');

  output.push({
    json: {
      tenant_id: lead.tenant_id || tenantId,
      lead_id: lead.id,
      deal_id: deal?.id || null,
      conversation_id: conversation?.id || null,
      lead,
      deal: deal || {},
      conversation: conversation || {},
      recent_messages: recentMessages,
      mensagemCliente: eventText,
      messageType: 'internal_followup',
      event_type: 'followup_resume',
      internal_behavioral_event: internalEvent,
      followup_task_id: task.id,
      followup_task: task,
      followup_delay_seconds: pickDelaySeconds(metadata),
      followup_due_at: task.due_at,
      followup_priority: task.priority,
      remoteJid: telefone,
      telefoneCompleto: telefone,
      sessionId: telefone,
      instance: firstText(conversation?.metadata?.instance, metadata.instance, 'Jurema Brokers'),
      origemLead: firstText(lead.source, lead.metadata?.origem, 'follow_up_task'),
      operational_context: {
        ...(asObject(conversation?.metadata?.operational_context)),
        followup_enabled: true,
        funnel_stage: 'followup',
        objective: firstText(strategy.goal, deal?.intent, lead.ai_last_intent, 'retomar_interesse'),
        preferred_regions: [firstText(conversationContext.bairro, deal?.location_preference)].filter(Boolean),
        favorite_property: firstText(conversationContext.property_reference, conversationContext.ultimo_imovel),
        metadata: {
          behavioral_state: behavioralState,
          conversation_context: conversationContext,
          strategy,
        },
      },
      runtime_memory: {
        event_type: 'followup_resume',
        next_best_action: firstText(strategy.goal, '').includes('imovel') ? 'apresentar_opcoes_aderentes' : 'retomar_contexto_consultivo',
        followup_task_id: task.id,
        followup_type: internalEvent.followup_type,
        recent_context: recentText(recentMessages),
      },
      _skip_ai: false,
    },
  });
}

return output;

