if (!payload.tenant_id) throw new Error('Runtime payload sem tenant_id.');
if (!payload.message) throw new Error('Runtime payload sem message.');

// UUID guard — runtime persiste ju_runtime_states (conversation_id UUID).
// Falha cedo se Build Context nao trouxer UUIDs validos, evita drift silencioso.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_RE.test(String(payload.conversation_id))) {
  throw new Error('Runtime payload conversation_id nao e UUID valido: ' + payload.conversation_id);
}
if (!UUID_RE.test(String(payload.tenant_id))) {
  throw new Error('Runtime payload tenant_id nao e UUID valido: ' + payload.tenant_id);
}

return [{
  json: {
    ...context,
    runtime_payload: payload,
    runtime_bridge: {
      enabled: true,
      fallback_policy: 'safe_text_and_manual_rollback',
      created_at: new Date().toISOString(),
    },
  },
}];

function nodeJson(name) {
  try { return $(name).first().json || {}; } catch (error) { return {}; }
}

function firstText(...values) {
  for (const value of values) {
    const text = String(value ?? '').trim();
    if (text) return text;
  }
  return '';
}

function validHttpUrl(value) {
  const text = String(value ?? '').trim();
  if (!/^https?:\/\//i.test(text)) return '';
  if (/localhost|127\.0\.0\.1/i.test(text)) return '';
  return text;
}

function collectCardUrls(value, seen = new Set()) {
  const urls = [];
  const visit = (entry) => {
    if (!entry) return;
    if (typeof entry === 'string') {
      const url = validHttpUrl(entry);
      if (url && !seen.has(url)) {
        seen.add(url);
        urls.push(url);
      }
      return;
    }
    if (Array.isArray(entry)) {
      for (const item of entry) visit(item);
      return;
    }
    if (typeof entry !== 'object') return;
    const candidates = [
      entry.url,
      entry.link,
      entry.link_do_imovel,
      entry.link_sanitizado,
      entry.public_url,
      entry.publicUrl,
      entry.property_url,
      entry.propertyUrl,
      entry.card_url,
      entry.cardUrl,
      entry.media_url,
      entry.thumbnail_url,
      entry.href,
    ];
    for (const candidate of candidates) visit(candidate);
    for (const key of ['cards', 'properties', 'imoveis', 'items', 'results', 'matches', 'tool_output', 'output']) {
      if (entry[key]) visit(entry[key]);
    }
  };
  visit(value);
  return urls;
}

function collectToolResultOutputs(runtime) {
  const buckets = [
    runtime.llm?.tool_results,
    runtime.result?.llm?.tool_results,
    runtime.tool_results,
    runtime.result?.tool_results,
  ];
  const outputs = [];
  for (const bucket of buckets) {
    if (!Array.isArray(bucket)) continue;
    for (const entry of bucket) {
      if (entry && entry.ok !== false && entry.output !== undefined && entry.output !== null) {
        outputs.push(entry.output);
      }
    }
  }
  return outputs;
}

const build = nodeJson('Build Context');
const prepared = nodeJson('Preparar Runtime Payload');
const runtime = $json || {};
const executionError = runtime.error || runtime.message?.error || runtime.cause || null;
const duplicate = runtime.duplicate === true || runtime.webhook?.duplicate === true;

const output = firstText(
  runtime.response_to_send,
  runtime.output,
  runtime.response,
  runtime.message,
  runtime.result?.response_to_send,
  runtime.result?.output,
  runtime.result?.llm?.output,
  runtime.llm?.output,
  runtime.decision?.output,
);

const toolOutputs = collectToolResultOutputs(runtime);
const cardUrls = collectCardUrls([
  runtime.messages,
  runtime.result?.messages,
  runtime.cards,
  runtime.result?.cards,
  ...toolOutputs,
]);

let finalOutput = output;
let fallbackReason = null;

if (duplicate) {
  finalOutput = '';
  fallbackReason = 'duplicate_message_dropped';
} else if (!finalOutput && cardUrls.length) {
  finalOutput = cardUrls.join('\n\n');
} else if (finalOutput && cardUrls.length) {
  const missingUrls = cardUrls.filter((url) => !finalOutput.includes(url));
  if (missingUrls.length) finalOutput = [finalOutput, ...missingUrls].join('\n\n');
} else if (!finalOutput) {
  fallbackReason = executionError ? 'runtime_error' : 'empty_runtime_output';
  finalOutput = 'Tive uma oscilacao aqui para processar sua mensagem. Vou retomar com seguranca: me confirma em uma frase o que voce quer priorizar agora?';
}

return [{
  json: {
    ...build,
    ...prepared,
    output: finalOutput,
    runtime_response: runtime,
    runtime_ok: runtime.ok === true && !executionError && Boolean(output || cardUrls.length),
    runtime_duplicate: duplicate,
    runtime_fallback: Boolean(fallbackReason),
    runtime_fallback_reason: fallbackReason,
    runtime_trace_id: runtime.trace_id || runtime.result?.trace_id || null,
    runtime_card_urls: cardUrls,
    response_to_send: runtime.response_to_send || null,
    conversation_id: firstText(build.conversation_id, prepared.conversation_id, runtime.conversation_id, runtime.runtime_payload?.conversation_id),
    tenant_id: firstText(build.tenant_id, prepared.tenant_id, runtime.tenant_id),
    lead_id: firstText(build.lead_id, prepared.lead_id, runtime.lead_id),
    deal_id: firstText(build.deal_id, prepared.deal_id, runtime.deal_id),
    remoteJid: firstText(build.remoteJid, prepared.remoteJid, prepared.runtime_payload?.remoteJid, prepared.runtime_payload?.conversation_id),
    telefoneCompleto: firstText(build.telefoneCompleto, prepared.telefoneCompleto, prepared.runtime_payload?.phone),
    sessionId: firstText(build.sessionId, prepared.sessionId, prepared.runtime_payload?.sessionId),
    event_type: build.event_type || prepared.event_type || null,
    followup_task_id: build.followup_task_id || prepared.followup_task_id || null,
    followup_task: build.followup_task || prepared.followup_task || null,
  },
}];
